const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const stFrancis = ee.Geometry.Point([-101.8, 39.77]); // St. Francis, Kansas
  const deathValley = ee.Geometry.Point([-116.82, 36.51]); // Death Valley, California
  const date = '2025-06-24';

  // 2. Data Acquisition
  const modis = ee.ImageCollection('MODIS/061/MOD11A1')
    .filterDate(date, ee.Date(date).advance(1, 'day'))
    .select(['LST_Day_1km', 'QC_Day']);

  const modisSize = modis.size().getInfo();
  console.log(`MODIS images found: ${modisSize}`);

  if (modisSize === 0) {
    console.log("No MODIS data available for June 24, 2025");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing function
  function maskLST(image) {
    const qc = image.select('QC_Day');
    const mask = qc.bitwiseAnd(3).eq(0); // Good quality pixels
    return image.select('LST_Day_1km').updateMask(mask);
  }

  const img = modis.map(maskLST).mean();

  // 4. Calculate temperatures for both locations
  const stFrancisStats = img.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: stFrancis.buffer(1000),
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const deathValleyStats = img.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: deathValley.buffer(1000),
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const stFrancisCount = stFrancisStats.LST_Day_1km_count || 0;
  const deathValleyCount = deathValleyStats.LST_Day_1km_count || 0;

  console.log(`St. Francis valid pixels: ${stFrancisCount}`);
  console.log(`Death Valley valid pixels: ${deathValleyCount}`);

  if (stFrancisCount === 0 || deathValleyCount === 0) {
    console.log("No valid pixels after masking");
    console.log("<answer>C2</answer>");
    return;
  }

  const stFrancisLST = stFrancisStats.LST_Day_1km_mean;
  const deathValleyLST = deathValleyStats.LST_Day_1km_mean;

  // 5. Validation & Convert to Celsius
  if (stFrancisLST == null || deathValleyLST == null || 
      isNaN(stFrancisLST) || isNaN(deathValleyLST)) {
    console.log("Temperature calculation failed");
    console.log("<answer>C3</answer>");
    return;
  }

  const stFrancisTemp = stFrancisLST * 0.02 - 273.15;
  const deathValleyTemp = deathValleyLST * 0.02 - 273.15;

  console.log(`St. Francis temperature: ${stFrancisTemp.toFixed(2)}°C`);
  console.log(`Death Valley temperature: ${deathValleyTemp.toFixed(2)}°C`);

  // Validate reasonable temperature range
  if (stFrancisTemp < -50 || stFrancisTemp > 70 || 
      deathValleyTemp < -50 || deathValleyTemp > 70) {
    console.log("Temperature out of reasonable range");
    console.log("<answer>C3</answer>");
    return;
  }

  // 6. Final Answer
  if (stFrancisTemp > deathValleyTemp) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
